update public.booking_events e set created_at = x.at
from (select e2.id, case when e2.type = 'created' then b.created_at
                          else coalesce(v.checked_in_at, b.cancelled_at, b.ends_at + interval '15 minutes') end as at
      from public.booking_events e2 join public.bookings b on b.id = e2.booking_id
      left join public.visits v on v.booking_id = b.id
      where b.idempotency_key like 'seed:%') x
where e.id = x.id and e.created_at is distinct from x.at;

