insert into public.venues (id, slug, name, description, category_id, tier, address, district, lat, lng, phone, website, tz, amenities, women_only_hours, cancellation_window_min, price_tier, status, created_at, updated_at) values
  ('aebd4df0-457a-56c4-ba15-e4dfb1231ab4', 'pulse-fitness-yunusabad', '{"ru":"Pulse Fitness Юнусабад","uz":"Pulse Fitness Yunusobod","en":"Pulse Fitness Yunusabad"}', '{"ru":"Просторный зал на двух этажах: свободные веса, кардиозона с видом на проспект и отдельная студия для групповых занятий. На первом визите тренер поможет составить программу.","uz":"Ikki qavatli keng zal: erkin ogʻirliklar, shoh koʻchaga qaragan kardio zonasi va guruh mashgʻulotlari uchun alohida studiya. Birinchi tashrifda murabbiy dastur tuzishga yordam beradi.","en":"A spacious two-floor gym with free weights, a cardio zone overlooking the avenue and a separate studio for group classes. On your first visit a coach will help you build a programme."}', '5fece9ac-8cd5-53fc-b916-c16c364e7791', 2, '{"ru":"просп. Амира Темура, 107Б, Юнусабадский район, Ташкент","uz":"Amir Temur shoh koʻchasi, 107B, Yunusobod tumani, Toshkent","en":"107B Amir Temur Avenue, Yunusabad District, Tashkent"}', 'yunusabad', 41.3432, 69.2968, '+998712953108', null, 'Asia/Tashkent', array['showers', 'lockers', 'parking', 'wifi', 'towels', 'air_conditioning', 'personal_training']::text[], null, 120, 2, 'active', '2026-06-29T10:00:00+05:00', '2026-06-29T10:00:00+05:00'),
  ('693ede47-641b-5567-927e-51a3eb1b8d7d', 'pulse-fitness-chilanzar', '{"ru":"Pulse Fitness Чиланзар","uz":"Pulse Fitness Chilonzor","en":"Pulse Fitness Chilanzar"}', '{"ru":"Зал сети Pulse рядом с метро «Чиланзар»: силовая зона, функциональный тренинг и сауна после тренировки. Открывается рано утром.","uz":"Pulse tarmogʻining «Chilonzor» metrosi yonidagi zali: kuch zonasi, funksional mashgʻulotlar va mashgʻulotdan keyin sauna. Erta tongdan ochiq.","en":"The Pulse club next to Chilanzar metro, with a strength zone, functional training and a sauna for after your workout. Opens early in the morning."}', '5fece9ac-8cd5-53fc-b916-c16c364e7791', 2, '{"ru":"просп. Бунёдкор, 42, Чиланзарский район, Ташкент","uz":"Bunyodkor shoh koʻchasi, 42, Chilonzor tumani, Toshkent","en":"42 Bunyodkor Avenue, Chilanzar District, Tashkent"}', 'chilanzar', 41.2853, 69.2142, '+998712954833', null, 'Asia/Tashkent', array['showers', 'lockers', 'sauna', 'wifi', 'towels']::text[], null, 120, 2, 'active', '2026-03-13T10:00:00+05:00', '2026-03-13T10:00:00+05:00'),
  ('ca8681b3-377c-5475-818e-169adbe437a1', 'kuch-gym-sergeli', '{"ru":"Kuch Gym","uz":"Kuch Gym","en":"Kuch Gym"}', '{"ru":"Районный зал без лишнего: штанги, гантели, тренажёры на все группы мышц и дружелюбная атмосфера. Удобно заниматься до и после работы.","uz":"Ortiqcha narsalarsiz mahalla zali: shtangalar, gantellar, barcha mushak guruhlari uchun trenajyorlar va samimiy muhit. Ishdan oldin va keyin shugʻullanish qulay.","en":"A no-frills neighbourhood gym with barbells, dumbbells, machines for every muscle group and a friendly crowd. Easy to fit in before or after work."}', '5fece9ac-8cd5-53fc-b916-c16c364e7791', 1, '{"ru":"ул. Янги Сергели, 11, Сергелийский район, Ташкент","uz":"Yangi Sergeli koʻchasi, 11, Sergeli tumani, Toshkent","en":"11 Yangi Sergeli Street, Sergeli District, Tashkent"}', 'sergeli', 41.2571, 69.2265, '+998712540065', null, 'Asia/Tashkent', array['showers', 'lockers', 'parking', 'water']::text[], null, 120, 1, 'active', '2026-03-17T10:00:00+05:00', '2026-03-17T10:00:00+05:00'),
  ('32792d45-a7ba-5082-8d1f-fcb63627ed60', 'atlas-club-mirabad', '{"ru":"Atlas Club","uz":"Atlas Club","en":"Atlas Club"}', '{"ru":"Премиальный клуб, открытый круглосуточно: новое оборудование, зона восстановления с хаммамом и свежие полотенца. Даже в часы пик здесь спокойно.","uz":"Kecha-kunduz ochiq premium klub: yangi jihozlar, hammomli tiklanish zonasi va toza sochiqlar. Gavjum soatlarda ham bu yerda osoyishta.","en":"A premium club open around the clock, with new equipment, a recovery area with a hammam and fresh towels. Calm even at peak hours."}', '5fece9ac-8cd5-53fc-b916-c16c364e7791', 3, '{"ru":"ул. Тараса Шевченко, 23, Мирабадский район, Ташкент","uz":"Taras Shevchenko koʻchasi, 23, Mirobod tumani, Toshkent","en":"23 Taras Shevchenko Street, Mirabad District, Tashkent"}', 'mirabad', 41.2989, 69.2817, '+998712162331', null, 'Asia/Tashkent', array['showers', 'lockers', 'parking', 'wifi', 'towels', 'sauna', 'cafe', 'air_conditioning', 'personal_training', 'hairdryer']::text[], null, 120, 3, 'active', '2026-07-21T10:00:00+05:00', '2026-07-21T10:00:00+05:00'),
  ('9dd406c3-0824-5d2c-8b60-ab04f531aea7', 'bars-fitness-almazar', '{"ru":"Bars Fitness","uz":"Bars Fitness","en":"Bars Fitness"}', '{"ru":"Зал рядом со студенческим городком: много свободных весов, турники и площадка для функциональных тренировок. По вечерам здесь людно и весело.","uz":"Talabalar shaharchasi yonidagi zal: koʻplab erkin ogʻirliklar, turniklar va funksional mashgʻulotlar maydonchasi. Kechqurunlari gavjum va qiziqarli.","en":"A gym next to the student campus with plenty of free weights, pull-up bars and a functional training area. Busy and lively in the evenings."}', '5fece9ac-8cd5-53fc-b916-c16c364e7791', 1, '{"ru":"ул. Фароби, 18, Алмазарский район, Ташкент","uz":"Forobiy koʻchasi, 18, Olmazor tumani, Toshkent","en":"18 Farobiy Street, Almazar District, Tashkent"}', 'almazar', 41.3451, 69.2196, '+998712771872', 'https://bars-fitness-almazar.example', 'Asia/Tashkent', array['showers', 'lockers', 'wifi', 'water']::text[], null, 120, 1, 'active', '2026-07-06T10:00:00+05:00', '2026-07-06T10:00:00+05:00'),
  ('311a2ded-2f05-5ba1-a548-74c52b2bd7b6', 'zilol-aqua-mirzo-ulugbek', '{"ru":"Аквацентр Zilol","uz":"Zilol akvamarkazi","en":"Zilol Aqua Centre"}', '{"ru":"Бассейн 25 метров на шесть дорожек с подогревом воды, детская чаша и инструкторы по плаванию. По вторникам и четвергам утром — женские часы.","uz":"Isitiladigan suvli olti yoʻlakli 25 metrlik basseyn, bolalar hovuzi va suzish boʻyicha instruktorlar. Seshanba va payshanba kunlari ertalab — ayollar uchun soatlar.","en":"A heated 25-metre pool with six lanes, a children’s pool and swimming instructors. Tuesday and Thursday mornings are women-only hours."}', '1f74afda-f47d-5692-aee9-4e994402f0aa', 2, '{"ru":"ул. Буюк Ипак Йули, 158, Мирзо-Улугбекский район, Ташкент","uz":"Buyuk Ipak Yoʻli koʻchasi, 158, Mirzo Ulugʻbek tumani, Toshkent","en":"158 Buyuk Ipak Yuli Street, Mirzo-Ulugbek District, Tashkent"}', 'mirzo-ulugbek', 41.3272, 69.3301, '+998712848742', 'https://zilol-aqua-mirzo-ulugbek.example', 'Asia/Tashkent', array['showers', 'lockers', 'hairdryer', 'towels', 'parking', 'kids_room']::text[], '[{"weekday":2,"opens":"10:00","closes":"13:00"},{"weekday":4,"opens":"10:00","closes":"13:00"}]', 120, 2, 'active', '2026-06-07T10:00:00+05:00', '2026-06-07T10:00:00+05:00'),
  ('9df7f61b-0096-57f5-b052-8889bff32687', 'delfin-pool-chilanzar', '{"ru":"Бассейн «Дельфин»","uz":"«Delfin» basseyni","en":"Delfin Pool"}', '{"ru":"Классический районный бассейн, где многие учились плавать. Свободное плавание, аквааэробика и женские часы по субботам.","uz":"Koʻpchilik suzishni oʻrgangan klassik mahalla basseyni. Erkin suzish, akvaaerobika va shanba kunlari ayollar uchun soatlar.","en":"A classic neighbourhood pool where many locals learned to swim. Lap swimming, aqua aerobics and women-only hours on Saturdays."}', '1f74afda-f47d-5692-aee9-4e994402f0aa', 1, '{"ru":"Чиланзар, 9-й квартал, 3А, Чиланзарский район, Ташкент","uz":"Chilonzor 9-mavze, 3A, Chilonzor tumani, Toshkent","en":"3A Chilanzar Block 9, Chilanzar District, Tashkent"}', 'chilanzar', 41.2781, 69.2027, '+998712368557', null, 'Asia/Tashkent', array['showers', 'lockers', 'hairdryer']::text[], '[{"weekday":6,"opens":"09:00","closes":"12:00"}]', 120, 1, 'active', '2026-07-06T10:00:00+05:00', '2026-07-06T10:00:00+05:00'),
  ('005540c5-712c-5969-97ec-a42c9acac62d', 'aqua-nur-yakkasaray', '{"ru":"Aqua Nur Club","uz":"Aqua Nur Club","en":"Aqua Nur Club"}', '{"ru":"Бассейн с морской водой, джакузи и панорамными окнами на парк. После плавания — финская сауна и травяной чай в лаунже.","uz":"Dengiz suvli basseyn, jakuzi va bogʻga qaragan panorama oynalari. Suzishdan keyin — fin saunasi va lounjda giyohli choy.","en":"A saltwater pool with a jacuzzi and panoramic windows onto the park. After your swim, a Finnish sauna and herbal tea in the lounge."}', '1f74afda-f47d-5692-aee9-4e994402f0aa', 3, '{"ru":"ул. Бобура, 76, Яккасарайский район, Ташкент","uz":"Bobur koʻchasi, 76, Yakkasaroy tumani, Toshkent","en":"76 Bobur Street, Yakkasaray District, Tashkent"}', 'yakkasaray', 41.2874, 69.2633, '+998712124003', null, 'Asia/Tashkent', array['showers', 'lockers', 'towels', 'sauna', 'hairdryer', 'cafe', 'parking', 'tea_lounge']::text[], null, 120, 3, 'active', '2026-07-01T10:00:00+05:00', '2026-07-01T10:00:00+05:00'),
  ('03afce4b-6ac3-5496-a729-66fffb1f444f', 'lotus-yoga-shaykhantahur', '{"ru":"Lotus Yoga Studio","uz":"Lotus Yoga Studio","en":"Lotus Yoga Studio"}', '{"ru":"Светлая студия в тихом дворе в центре города. Хатха, виньяса и йога-нидра для любого уровня, коврики и пледы выдаём.","uz":"Shahar markazidagi sokin hovlida joylashgan yorugʻ studiya. Har qanday daraja uchun xatha, vinyasa va yoga-nidra; gilamcha va pled beriladi.","en":"A bright studio in a quiet courtyard in the city centre. Hatha, vinyasa and yoga nidra for every level; mats and blankets provided."}', '0b32291e-48ef-59d5-9df7-b6c6a80ec4f8', 2, '{"ru":"ул. Абая, 4, Шайхантахурский район, Ташкент","uz":"Abay koʻchasi, 4, Shayxontohur tumani, Toshkent","en":"4 Abay Street, Shaykhantahur District, Tashkent"}', 'shaykhantahur', 41.3163, 69.2471, '+998712780820', null, 'Asia/Tashkent', array['mats_provided', 'showers', 'lockers', 'tea_lounge', 'wifi']::text[], null, 120, 2, 'active', '2026-04-12T10:00:00+05:00', '2026-04-12T10:00:00+05:00'),
  ('9b56c39e-dc56-55e9-a7c1-e88bf903b3ae', 'nafas-yoga-yunusabad', '{"ru":"Nafas Yoga","uz":"Nafas Yoga","en":"Nafas Yoga"}', '{"ru":"Небольшая студия у Юнусабадского парка: утренняя практика перед работой и мягкая йога по вечерам. Хорошее место, чтобы начать.","uz":"Yunusobod bogʻi yonidagi kichik studiya: ish oldidan ertalabki amaliyot va kechqurun yumshoq yoga. Boshlash uchun yaxshi joy.","en":"A small studio by Yunusabad park, with morning practice before work and gentle yoga in the evenings. A good place to start."}', '0b32291e-48ef-59d5-9df7-b6c6a80ec4f8', 1, '{"ru":"ул. Богишамол, 21, Юнусабадский район, Ташкент","uz":"Bogʻishamol koʻchasi, 21, Yunusobod tumani, Toshkent","en":"21 Bogishamol Street, Yunusabad District, Tashkent"}', 'yunusabad', 41.3587, 69.2862, '+998712667681', null, 'Asia/Tashkent', array['mats_provided', 'lockers', 'water']::text[], null, 120, 1, 'active', '2026-06-20T10:00:00+05:00', '2026-06-20T10:00:00+05:00'),
  ('6a4f6c73-bf43-53dc-b4d7-a44e981d9e24', 'oqim-yoga-loft-mirabad', '{"ru":"Oqim Yoga Loft","uz":"Oqim Yoga Loft","en":"Oqim Yoga Loft"}', '{"ru":"Лофт с высокими потолками и тёплым полом. Аштанга, йога в гамаках и звуковые медитации с опытными преподавателями.","uz":"Shiftlari baland va pollari isitiladigan loft. Tajribali ustozlar bilan ashtanga, gamakda yoga va tovushli meditatsiyalar.","en":"A loft with high ceilings and heated floors. Ashtanga, aerial yoga and sound meditation with experienced teachers."}', '0b32291e-48ef-59d5-9df7-b6c6a80ec4f8', 3, '{"ru":"ул. Афросиаб, 12, Мирабадский район, Ташкент","uz":"Afrosiyob koʻchasi, 12, Mirobod tumani, Toshkent","en":"12 Afrosiyob Street, Mirabad District, Tashkent"}', 'mirabad', 41.3051, 69.2875, '+998712344889', 'https://oqim-yoga-loft-mirabad.example', 'Asia/Tashkent', array['mats_provided', 'showers', 'lockers', 'towels', 'tea_lounge', 'air_conditioning']::text[], null, 120, 3, 'active', '2026-03-06T10:00:00+05:00', '2026-03-06T10:00:00+05:00'),
  ('76ce1cc6-7bab-5dea-9f56-8c1a0ea4f2c6', 'core-pilates-yakkasaray', '{"ru":"Core Pilates Studio","uz":"Core Pilates Studio","en":"Core Pilates Studio"}', '{"ru":"Студия пилатеса на реформерах: занятия в мини-группах до шести человек, внимание к технике и восстановлению после травм.","uz":"Reformerlarda pilates studiyasi: oltitagacha kishilik kichik guruhlarda mashgʻulotlar, texnika va jarohatdan keyin tiklanishga eʼtibor.","en":"A reformer Pilates studio with small groups of up to six and close attention to technique and injury recovery."}', 'df0de8ef-8276-5fc7-96bd-a2a0689ce4ea', 3, '{"ru":"ул. Шота Руставели, 41, Яккасарайский район, Ташкент","uz":"Shota Rustaveli koʻchasi, 41, Yakkasaroy tumani, Toshkent","en":"41 Shota Rustaveli Street, Yakkasaray District, Tashkent"}', 'yakkasaray', 41.2932, 69.2684, '+998712481959', 'https://core-pilates-yakkasaray.example', 'Asia/Tashkent', array['showers', 'lockers', 'towels', 'air_conditioning']::text[], null, 720, 3, 'active', '2026-07-18T10:00:00+05:00', '2026-07-18T10:00:00+05:00'),
  ('bff0c06f-d348-5d10-a930-549d35003da2', 'muvozanat-pilates-mirzo-ulugbek', '{"ru":"Muvozanat Pilates","uz":"Muvozanat Pilates","en":"Muvozanat Pilates"}', '{"ru":"Пилатес на ковриках и с малым оборудованием: укрепляем спину, корпус и осанку. Удобно для тех, кто весь день сидит за компьютером.","uz":"Gilamchada va kichik jihozlar bilan pilates: bel, tana va qomatni mustahkamlaymiz. Kun boʻyi kompyuter oldida oʻtiradiganlar uchun qulay.","en":"Mat Pilates and small-equipment classes that strengthen your back, core and posture. Ideal if you spend all day at a desk."}', 'df0de8ef-8276-5fc7-96bd-a2a0689ce4ea', 2, '{"ru":"просп. Мустакиллик, 59, Мирзо-Улугбекский район, Ташкент","uz":"Mustaqillik shoh koʻchasi, 59, Mirzo Ulugʻbek tumani, Toshkent","en":"59 Mustaqillik Avenue, Mirzo-Ulugbek District, Tashkent"}', 'mirzo-ulugbek', 41.3184, 69.3076, '+998712066919', 'https://muvozanat-pilates-mirzo-ulugbek.example', 'Asia/Tashkent', array['mats_provided', 'showers', 'lockers', 'wifi']::text[], null, 120, 2, 'active', '2026-04-22T10:00:00+05:00', '2026-04-22T10:00:00+05:00'),
  ('b59921a3-0ece-53c0-a406-dadb1938b5a2', 'ritm-dance-shaykhantahur', '{"ru":"Школа танцев Ritm","uz":"Ritm raqs maktabi","en":"Ritm Dance School"}', '{"ru":"Хип-хоп, бачата и современная хореография для взрослых. Группы для новичков стартуют каждый месяц, партнёр не нужен.","uz":"Kattalar uchun xip-xop, bachata va zamonaviy xoreografiya. Yangi boshlovchilar guruhlari har oy ochiladi, sherik shart emas.","en":"Hip-hop, bachata and contemporary choreography for adults. Beginner groups start every month, and no partner is needed."}', '50c9f243-53e6-5a4f-826a-be2dabc23ad2', 1, '{"ru":"ул. Лабзак, 7, Шайхантахурский район, Ташкент","uz":"Labzak koʻchasi, 7, Shayxontohur tumani, Toshkent","en":"7 Labzak Street, Shaykhantahur District, Tashkent"}', 'shaykhantahur', 41.3248, 69.2569, '+998712776957', 'https://ritm-dance-shaykhantahur.example', 'Asia/Tashkent', array['showers', 'lockers', 'water', 'air_conditioning']::text[], null, 120, 1, 'active', '2026-03-20T10:00:00+05:00', '2026-03-20T10:00:00+05:00'),
  ('1894a3a1-22e9-5804-b7c7-51baafe80e8d', 'raqs-studio-chilanzar', '{"ru":"Raqs Studio","uz":"Raqs Studio","en":"Raqs Studio"}', '{"ru":"Зумба, восточные и национальные танцы в большом зале с зеркалами. Весёлые тренировки, после которых хочется вернуться.","uz":"Koʻzgular bilan jihozlangan katta zalda zumba, sharq va milliy raqslar. Yana qaytgingiz keladigan quvnoq mashgʻulotlar.","en":"Zumba, oriental and Uzbek folk dance in a big mirrored hall. Fun workouts that keep you coming back."}', '50c9f243-53e6-5a4f-826a-be2dabc23ad2', 1, '{"ru":"ул. Мукими, 104, Чиланзарский район, Ташкент","uz":"Muqimiy koʻchasi, 104, Chilonzor tumani, Toshkent","en":"104 Muqimiy Street, Chilanzar District, Tashkent"}', 'chilanzar', 41.2921, 69.2301, '+998712016454', 'https://raqs-studio-chilanzar.example', 'Asia/Tashkent', array['lockers', 'water', 'air_conditioning']::text[], null, 120, 1, 'active', '2026-04-03T10:00:00+05:00', '2026-04-03T10:00:00+05:00'),
  ('0b11294e-d602-5ee8-893d-507c96e72400', 'samurai-dojo-mirzo-ulugbek', '{"ru":"Samurai Dojo","uz":"Samurai Dojo","en":"Samurai Dojo"}', '{"ru":"Дзюдо и карате для взрослых в просторном зале с татами. Тренеры — мастера спорта, на первое занятие можно прийти без кимоно.","uz":"Tatamili keng zalda kattalar uchun dzyudo va karate. Murabbiylar — sport ustalari, birinchi mashgʻulotga kimonosiz kelish mumkin.","en":"Judo and karate for adults in a spacious tatami hall. The coaches are masters of sport, and you can come to your first class without a gi."}', '1d2a0f99-12c2-5315-b758-79c0bba34b55', 1, '{"ru":"ул. Паркентская, 45, Мирзо-Улугбекский район, Ташкент","uz":"Parkent koʻchasi, 45, Mirzo Ulugʻbek tumani, Toshkent","en":"45 Parkent Street, Mirzo-Ulugbek District, Tashkent"}', 'mirzo-ulugbek', 41.3354, 69.3448, '+998712338396', 'https://samurai-dojo-mirzo-ulugbek.example', 'Asia/Tashkent', array['showers', 'lockers', 'water', 'parking']::text[], null, 120, 1, 'active', '2026-06-15T10:00:00+05:00', '2026-06-15T10:00:00+05:00'),
  ('a0d13c73-d105-55e3-886a-317cb111ff98', 'lochin-fight-club-yunusabad', '{"ru":"Lochin Fight Club","uz":"Lochin Fight Club","en":"Lochin Fight Club"}', '{"ru":"Бокс, кикбоксинг и ММА: ринг, клетка и зона мешков. Тренировки для новичков и спарринги для тех, кто готов.","uz":"Boks, kikboksing va MMA: ring, qafas va qopchalar zonasi. Yangi boshlovchilar uchun mashgʻulotlar va tayyorlar uchun sparringlar.","en":"Boxing, kickboxing and MMA with a ring, a cage and a bag zone. Beginner sessions plus sparring for those who are ready."}', '1d2a0f99-12c2-5315-b758-79c0bba34b55', 2, '{"ru":"ул. Ахмада Дониша, 32, Юнусабадский район, Ташкент","uz":"Ahmad Donish koʻchasi, 32, Yunusobod tumani, Toshkent","en":"32 Ahmad Donish Street, Yunusabad District, Tashkent"}', 'yunusabad', 41.3651, 69.2905, '+998712016159', 'https://lochin-fight-club-yunusabad.example', 'Asia/Tashkent', array['showers', 'lockers', 'equipment_rental', 'water']::text[], null, 120, 2, 'active', '2026-05-24T10:00:00+05:00', '2026-05-24T10:00:00+05:00'),
  ('128bbcde-6ea3-54c8-bad9-ce3cc4ec7964', 'polvon-kurash-almazar', '{"ru":"Клуб курэша «Полвон»","uz":"«Polvon» kurash klubi","en":"Polvon Kurash Club"}', '{"ru":"Курэш — национальная борьба — и вольная борьба для взрослых. Сильные тренеры, дружная команда и честная нагрузка.","uz":"Kattalar uchun milliy kurash va erkin kurash. Kuchli murabbiylar, inoq jamoa va jiddiy mashgʻulotlar.","en":"Kurash, Uzbekistan’s national wrestling, plus freestyle wrestling for adults. Strong coaches, a close-knit team and honest hard work."}', '1d2a0f99-12c2-5315-b758-79c0bba34b55', 1, '{"ru":"ул. Карасарай, 15, Алмазарский район, Ташкент","uz":"Qorasaroy koʻchasi, 15, Olmazor tumani, Toshkent","en":"15 Qorasaroy Street, Almazar District, Tashkent"}', 'almazar', 41.3332, 69.2381, '+998712536896', 'https://polvon-kurash-almazar.example', 'Asia/Tashkent', array['showers', 'lockers', 'water']::text[], null, 120, 1, 'active', '2026-04-16T10:00:00+05:00', '2026-04-16T10:00:00+05:00'),
  ('9575a41a-a3d2-59a6-98ca-c5930862e3a1', 'forge-box-mirabad', '{"ru":"Forge Box","uz":"Forge Box","en":"Forge Box"}', '{"ru":"Функциональный бокс с тренировкой дня, олимпийской тяжёлой атлетикой и гимнастикой. Каждое занятие ведёт тренер, нагрузку подбираем под ваш уровень.","uz":"Kun mashgʻuloti, olimpiya ogʻir atletikasi va gimnastika bilan funksional boks. Har bir mashgʻulotni murabbiy olib boradi, yuklamani darajangizga moslaymiz.","en":"A functional fitness box with a workout of the day, Olympic weightlifting and gymnastics. Every class is coached and scaled to your level."}', '90ce7f2b-edd7-5201-a76d-18654009f09d', 2, '{"ru":"ул. Нукусская, 54, Мирабадский район, Ташкент","uz":"Nukus koʻchasi, 54, Mirobod tumani, Toshkent","en":"54 Nukus Street, Mirabad District, Tashkent"}', 'mirabad', 41.2956, 69.2763, '+998712278704', 'https://forge-box-mirabad.example', 'Asia/Tashkent', array['showers', 'lockers', 'water', 'parking']::text[], null, 120, 2, 'active', '2026-04-18T10:00:00+05:00', '2026-04-18T10:00:00+05:00'),
  ('c6975047-2553-54c3-8939-9fe3211e48ff', 'chaqmoq-box-sergeli', '{"ru":"Chaqmoq Box","uz":"Chaqmoq Box","en":"Chaqmoq Box"}', '{"ru":"Небольшой бокс с короткими интенсивными тренировками по 45 минут. Отличный вариант для тех, кто ценит время.","uz":"45 daqiqalik qisqa va jadal mashgʻulotlarga ega kichik boks. Vaqtini qadrlaydiganlar uchun ajoyib tanlov.","en":"A small box with short, intense 45-minute workouts. A great choice if your time is precious."}', '90ce7f2b-edd7-5201-a76d-18654009f09d', 1, '{"ru":"ул. Чоштепа, 9, Сергелийский район, Ташкент","uz":"Choshtepa koʻchasi, 9, Sergeli tumani, Toshkent","en":"9 Choshtepa Street, Sergeli District, Tashkent"}', 'sergeli', 41.2534, 69.2318, '+998712869180', 'https://chaqmoq-box-sergeli.example', 'Asia/Tashkent', array['showers', 'lockers', 'water']::text[], null, 120, 1, 'active', '2026-05-01T10:00:00+05:00', '2026-05-01T10:00:00+05:00'),
  ('ce697d48-4e44-525a-862d-870628485fd5', 'oasis-spa-mirabad', '{"ru":"Oasis Spa & Wellness","uz":"Oasis Spa & Wellness","en":"Oasis Spa & Wellness"}', '{"ru":"Спа-комплекс с бассейном, хаммамом, соляной комнатой и зоной отдыха. Идеально, чтобы выдохнуть после длинной недели.","uz":"Basseyn, hammom, tuz xonasi va dam olish zonasiga ega spa majmuasi. Uzoq haftadan keyin nafas rostlash uchun ayni muddao.","en":"A spa complex with a pool, a hammam, a salt room and a relaxation lounge. Perfect for unwinding after a long week."}', 'ed0db951-a707-589f-835b-6bdafd59ea61', 3, '{"ru":"ул. Мовароуннахр, 1, Мирабадский район, Ташкент","uz":"Movarounnahr koʻchasi, 1, Mirobod tumani, Toshkent","en":"1 Movarounnahr Street, Mirabad District, Tashkent"}', 'mirabad', 41.3069, 69.2742, '+998712877542', null, 'Asia/Tashkent', array['showers', 'lockers', 'towels', 'pool', 'sauna', 'tea_lounge', 'hairdryer', 'parking']::text[], null, 240, 3, 'active', '2026-06-25T10:00:00+05:00', '2026-06-25T10:00:00+05:00'),
  ('a953e770-d7b8-597f-babe-9fafd3d5583f', 'bahor-spa-yunusabad', '{"ru":"Bahor Spa","uz":"Bahor Spa","en":"Bahor Spa"}', '{"ru":"Уютный спа с травяной парной, массажными кабинетами и чайной комнатой. По средам днём — часы только для женщин.","uz":"Giyohli bugʻxona, massaj xonalari va choyxonali shinam spa. Chorshanba kunlari kunduzi — faqat ayollar uchun soatlar.","en":"A cosy spa with a herbal steam room, massage rooms and a tea room. Wednesday daytime is reserved for women."}', 'ed0db951-a707-589f-835b-6bdafd59ea61', 2, '{"ru":"ул. Осиё, 8, Юнусабадский район, Ташкент","uz":"Osiyo koʻchasi, 8, Yunusobod tumani, Toshkent","en":"8 Osiyo Street, Yunusabad District, Tashkent"}', 'yunusabad', 41.3511, 69.2799, '+998712466808', 'https://bahor-spa-yunusabad.example', 'Asia/Tashkent', array['showers', 'lockers', 'towels', 'tea_lounge', 'hairdryer']::text[], '[{"weekday":3,"opens":"10:00","closes":"15:00"}]', 120, 2, 'active', '2026-06-06T10:00:00+05:00', '2026-06-06T10:00:00+05:00'),
  ('d3c426da-8dd7-53f6-9bcf-70e9dc2b2139', 'sharq-hammam-shaykhantahur', '{"ru":"Хаммам «Шарк»","uz":"«Sharq» hammomi","en":"Sharq Hammam"}', '{"ru":"Восточная баня в старом городе: горячий мрамор, кесе-пилинг и пенный массаж. В понедельник и четверг до 15:00 — только для женщин.","uz":"Eski shahardagi sharqona hammom: issiq marmar, kesa-piling va koʻpikli massaj. Dushanba va payshanba kunlari soat 15:00 gacha — faqat ayollar uchun.","en":"An oriental bathhouse in the old city with hot marble, a kese scrub and foam massage. Monday and Thursday until 3 pm are women-only."}', 'c5ac33b5-7e12-57cf-a116-8d97b5fcfe4b', 2, '{"ru":"ул. Заркайнар, 27, Шайхантахурский район, Ташкент","uz":"Zarqaynar koʻchasi, 27, Shayxontohur tumani, Toshkent","en":"27 Zarqaynar Street, Shaykhantahur District, Tashkent"}', 'shaykhantahur', 41.3197, 69.2412, '+998712880249', null, 'Asia/Tashkent', array['showers', 'lockers', 'towels', 'tea_lounge']::text[], '[{"weekday":1,"opens":"09:00","closes":"15:00"},{"weekday":4,"opens":"09:00","closes":"15:00"}]', 120, 2, 'active', '2026-04-14T10:00:00+05:00', '2026-04-14T10:00:00+05:00'),
  ('3699940e-e871-5f6b-a250-7afbc7202d99', 'kedr-banya-chilanzar', '{"ru":"Баня «Кедр»","uz":"«Kedr» saunasi","en":"Kedr Banya"}', '{"ru":"Русская баня на дровах и финская сауна с купелью. По пятницам и субботам открыто до двух ночи.","uz":"Oʻtinda isitiladigan rus hammomi va sovuq suvli hovuzchali fin saunasi. Juma va shanba kunlari tungi soat ikkigacha ochiq.","en":"A wood-fired Russian banya and a Finnish sauna with a plunge pool. Open until 2 am on Fridays and Saturdays."}', 'c5ac33b5-7e12-57cf-a116-8d97b5fcfe4b', 1, '{"ru":"ул. Гавхар, 133, Чиланзарский район, Ташкент","uz":"Gavhar koʻchasi, 133, Chilonzor tumani, Toshkent","en":"133 Gavhar Street, Chilanzar District, Tashkent"}', 'chilanzar', 41.2829, 69.2205, '+998712757225', null, 'Asia/Tashkent', array['showers', 'lockers', 'towels', 'tea_lounge', 'parking']::text[], null, 120, 1, 'active', '2026-05-25T10:00:00+05:00', '2026-05-25T10:00:00+05:00'),
