insert into public.class_templates (id, venue_id, name, description, duration_min, capacity, trainer_id, level) values
  ('88f8ec73-cc2c-51b4-b305-8948224b8ff4', 'aebd4df0-457a-56c4-ba15-e4dfb1231ab4', '{"ru":"Функциональный тренинг","uz":"Funksional mashgʻulot","en":"Functional training"}', '{"ru":"Круговая тренировка с собственным весом, гирями и эспандерами.","uz":"Oʻz vazni, gantellar va rezina lentalar bilan aylanma mashgʻulot.","en":"A circuit workout with bodyweight, kettlebells and resistance bands."}', 55, 14, '68021737-7dcc-5a14-8874-b5370203f40e', 'any'),
  ('c3b509da-59d5-5a91-947f-3b8787e41947', 'aebd4df0-457a-56c4-ba15-e4dfb1231ab4', '{"ru":"Интервальная тренировка HIIT","uz":"HIIT intervalli mashgʻulot","en":"HIIT intervals"}', '{"ru":"Короткие интенсивные интервалы, чтобы разогнать пульс и сжечь калории.","uz":"Pulsni tezlashtirish va kaloriya yoqish uchun qisqa va jadal intervallar.","en":"Short, intense intervals to raise your heart rate and burn calories."}', 45, 16, '7ba502a8-f718-52f3-9d12-dc43d004f8bb', 'intermediate'),
